report <- function() {
  p <- progressor(steps = 4)
  cat(length(p), "\n", sep = "")
  p(message = "one")
  p(message = "two")
  p(message = "three")
  p(message = "four")
}
handler <- make_progression_handler("rec", reporter = list(
  update = function(config, state, progression, ...) {
    cat(progression$type, " ", progression$amount, " ", conditionMessage(progression), "\n", sep = "")
  }
), enable = TRUE, target = "file", interval = 0)
with_progress(report(), handlers = handler, enable = TRUE, interval = 0,
  delay_terminal = FALSE, delay_stdout = FALSE, delay_conditions = character())
